/// An amount: (field, cents, currency, quality).
pub(super) type A = (&'static str, i64, &'static str, Option<&'static str>);
/// A lot award: (result key, lot key, cents, currency).
pub(super) type R = (&'static str, Option<&'static str>, Option<i64>, Option<&'static str>);

/// One version: tender-scope amounts, lots as (key, kind, amounts), rounds as (notice id, awards).
pub(super) struct V {
    pub facts: &'static [A],
    pub lots: &'static [(&'static str, &'static str, &'static [A])],
    pub rounds: &'static [(i64, &'static [R])],
}

/// One Tender: its id, the rates (units per EUR) of its non-EUR currencies, its chain oldest first.
pub(super) struct Fixture {
    pub id: i64,
    pub rates: &'static [(&'static str, f64)],
    pub chain: &'static [V],
}

/// The fixtures' publication instant (2023-11-14), at which their rates are seeded.
pub(super) const PUBLISHED_AT: i64 = 1_700_000_000;

impl Fixture {
    /// The chain as [`TenderVersion`]s, each version caused by its own notice.
    pub fn versions(&self) -> Vec<TenderVersion> {
        let amount = |&(field, cents, currency, quality): &A| Fact::Amount {
            field: field.into(),
            cents,
            currency: currency.into(),
            tax_basis: None,
            quality: quality.map(Into::into),
        };
        self.chain
            .iter()
            .enumerate()
            .map(|(i, v)| TenderVersion {
                caused_by_notice_id: i as i64 + 1,
                published_at: PUBLISHED_AT,
                dispatched_at: None,
                notice_subtype: None,
                original_lang: None,
                publication_id: format!("{}-{}", self.id, i + 1),
                facts: v.facts.iter().map(amount).collect(),
                lots: v.lots.iter().map(|(key, kind, facts)| LotState { key: (*key).into(), kind: (*kind).into(), facts: facts.iter().map(amount).collect(), published_lot_no: None }).collect(),
                rounds: v
                    .rounds
                    .iter()
                    .map(|(notice_id, awards)| Round {
                        notice_id: *notice_id,
                        logical_notice_id: None,
                        lot_results: awards
                            .iter()
                            .map(|&(key, lot_key, cents, currency)| LotResultState {
                                key: key.into(),
                                lot_key: lot_key.map(Into::into),
                                decision: None,
                                reason: None,
                                awarded_cents: cents,
                                awarded_currency: currency.map(Into::into),
                                decided: None,
                                winners: Vec::new(),
                                buyer_winners: Vec::new(),
                                statistics: Vec::new(),
                                published_lot_no: None,
                                group: false,
                            })
                            .collect(),
                        bids: Vec::new(),
                        contracts: Vec::new(),
                    })
                    .collect(),
                group_members: Vec::new(),
                stated_totals: Vec::new(),
            })
            .collect()
    }

    /// A rates lookup holding the fixture's rates at [`PUBLISHED_AT`]'s date.
    pub fn rates(&self) -> crate::rates::RatesLookup {
        let mut rates = crate::rates::RatesLookup::default();
        let date = crate::rates::civil_date(PUBLISHED_AT);
        for (currency, per_eur) in self.rates {
            rates.insert_for_test(currency, &date, *per_eur);
        }
        rates
    }
}

